import{_ as t,o as e,c as o,a3 as s}from"./chunks/framework.BwzYn71E.js";const c=JSON.parse('{"title":"成果公开流程问题总结","description":"","frontmatter":{"translationSource":{"title":"成果公开流程问题总结","archivedAt":"2026-10-31","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=bjB7jF3g7E11H2AlmcZ3JQ","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/issues-with-publishing-results"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/issues-with-publishing-results"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/issues-with-publishing-results"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/issues-with-publishing-results"}]]},"headers":[],"relativePath":"zh/issues-with-publishing-results.md","filePath":"zh/page-bjB7jF3g7E11H2AlmcZ3JQ.md"}'),i={name:"zh/issues-with-publishing-results.md"};function r(a,p,l,n,u,d){return e(),o("div",null,[...p[0]||(p[0]=[s('<div class="logistics-content"><span class="logistics-source-anchor" id="成果公开流程问题总结" aria-hidden="true"></span><h1 id="成果公开流程问题总结" tabindex="-1">成果公开流程问题总结 <a class="header-anchor" href="#成果公开流程问题总结" aria-label="Permalink to &quot;成果公开流程问题总结&quot;">​</a></h1><blockquote><p>源页面 ID：<code>bjB7jF3g7E11H2AlmcZ3JQ</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=bjB7jF3g7E11H2AlmcZ3JQ" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>应收集在成果公开过程中出现的问题与群友建议，包括：技术文档编写、视频制作、视频反馈影响、售后等方面</p><p><strong>Q1 蓝图码是否有必要</strong></p><p>简述：视频给出蓝图码，但整体内容偏向半劝退，是否自相矛盾、没必要</p><p>四卡一：先问自己到底做给谁看——如果是炫技，那就完全没有蓝图码的必要；如果是面向大众的作业，就努力优化适配；而不是现在这样半劝退着来，两边都吃力不讨好</p><p>言：有必要；要强调定位；我的意见是指出缺点，尤其是&quot;自查地狱&quot;</p><p>鸟：还是有必要的，至少想学的可以拿去学</p><p>加兰斯：下次视频前先叠甲，先说清楚需要一定基建基础</p><p>（09-16）</p><p><strong>Q2 蓝图码应该放在哪里</strong></p><p>简述：任务板公开文档中，蓝图码放在文档前面还是后面</p><p>[Ѵ. Ŋøᵰę]ᵱ：面向大众的话，第一件事先把文档蓝图码往前放；然后常见问题；详细技术细节开子页面；那就先常见问题、然后蓝图码、其它全部放进子页面；建议再开一期视频深情朗读《提问的艺术》</p><p>言：往前面放，后面的就都不看了，到时用坏了又来问；往后面放算是强制粗略阅读文档；被 K 说服后改口&quot;那我还是放到前面吧&quot;</p><p>K：粗读也就是瞟一眼有没有蓝图码，就像软件使用前的用户协议一样没用（像 maa 弹公告要求拉到底才能关，也不影响一部分人根本不看）</p><p>Cipolla_：这个蓝图码在常见问题后面是认真的吗；好想直接上手改</p><p>BEAR：蓝图码丢文档里面去，摆放放 2p</p><p>言（塔卫二，09-08）：简介补一下说&quot;蓝图码更新比文档慢&quot;，让他们优先看文档</p><p>（09-16；塔卫二 09-08）</p><p><strong>Q3 缺乏统一决策与校对</strong></p><p>简述：各干各的、对接不上，工作分配不正常，成果缺乏校对</p><p>区：规模上来了，统筹安排拍板运营没跟上</p><p>K：言大人很厉害，但是我们缺一个主心骨／缺个指挥部／没有能统筹的，或者能背锅的</p><p>BEAR：我们根本没有 ddl；老大你下次要抓 ddl</p><p>S：咱真得有个校对组了；各干各的，对接不上</p><p>[Ѵ. Ŋøᵰę]ᵱ：我都不知道我文档里的蓝图码现在和视频对不上；以后改别人写的文档至少小窗说一声</p><p>言：坏了，我以为你的景玉谷和原来一样，我直接把链接拿过去了</p><p>（09-16）</p><p>塔卫二（08-03）忉牿：出错太正常了，不出错才是稀罕事；急急急妞呢小：就是出错很多啊，感觉没有校对甚至都没看就直接印了；君：上哪给你找个校对，要花钱啊；苍孤狼：ai 校对一遍很难吗 → 忉牿：ai 校对就能校对成功吗 → 苍孤狼：人校对就能校对成功吗，没有 100% 的事情，但肯定比现在所描述的要好得多</p><p><strong>Q4 售后与客服负担</strong></p><p>简述：成果发布后的答疑与售后压力大，人手不足，责任归属也不清楚</p><p>言：售后这一块有没有合作的可能；我们也没力气售后；和大 up 合作的必要性在于他们很擅长售后、对用户需求也比我们了解</p><p>BEAR：倒不如担心售后出问题了算谁的</p><p>鸟：算售后的（x）；培养客服君（x）</p><p>区：最苦最累还挨抱怨吗</p><p>君：不发工资怎么专心面向玩家</p><p>麻：兼职客服都没怎么做</p><p>阳桃：是不是考虑开专门的售后群了（）</p><p>Zirunwang：客服做时间长了就麻木了</p><p>Witherlin凋灵灵：可不可以用群资源去喂 AI，搓一个 AI 客服</p><p>二律背反：这两天我售后直播——&quot;主播我龙泡泡为什么不生产&quot;，一看，配方没解锁；再弱保软的蓝图，看完评论区只恨还不够弱保软</p><p>塔卫二：☢caution☢&quot;服务不是很到位，别人一看这个人做蓝图没有售后&quot;；Fatal Error A1012&quot;你可以搜视频，但你需要自行启动、离线再调试，所以不负责售后&quot;</p><p>（09-12 ~ 09-26；塔卫二 04-19、05-06）</p><p><strong>Q5 文档过长导致受众被劝退</strong></p><p>百亿亿亿亿：我也把文档链接给过他们，只不过很多人被巨量的文字劝退了；应该可以不劝退不会基建的人</p><p>良木：别想了，大部分人估计都不会看文档</p><p>断懒：视频里有的内容都不会有人看的；我视频里强调了 3 遍的事情都有人来问我为什么；建议直接出个分 p 讲解所有可能遇到的问题；留着工程文档，每周更新一次</p><p>二律背反：视频里也没人看；再简单他们都不会</p><p>区：弱保软是没有尽头的；大学课程应该不用考虑小学生学习</p><p>Cipolla_：大部分人是不看常见问题也没啥问题；如果要面对有一定基础或一定兴趣的观众，那我们的技术讲解视频该端上来了</p><p>Q6 蓝图码 / 视频 / 文档三者不同步</p><p>简述：改版、改字、换号都会让蓝图码与视频、文档对不上，观众拿到的是错码</p><p>四卡一：我遇到的非常多的问题——为什么蓝图码失效了，多到我懒得吐槽；最早的蓝图码是错了是吧</p><p>言：这次这套蓝图，很多人的错误是酸、水、惰气没接上</p><p>[Ѵ. Ŋøᵰę]ᵱ：你们改过的那个和我视频对不上</p><p>夏后曦和：很想吐槽终末地的蓝图系统，改一个字重新保存，共享蓝图码都会变；出问题时我会第一时间怀疑我的蓝图是不是有 bug</p><p>盒え猫：不是一个人写的</p><p>K：任务板确实挺乱的；有去你的全物品文档的超链接的，要删掉吗</p><p>断懒：蓝图码不要手输入或者截图输入；蓝图码前后不要有空格</p><p>PL：蓝图有字数限制，视频简介里放蓝图码的地方能写下吗，视频介绍摆放时也能说</p><p>BEAR：要不要专门建一个最指定的给 1.5 毛的蓝图码</p><p>jnk（塔卫二）：蓝图码留的 uid 是大号，但视频上是小号</p><p>言（09-26）：不应该想着把蓝图码放进压缩包吗</p><p><strong>Q7 成果到底做给谁看：炫技、攻略还是科普</strong></p><p>简述：团队始终没把&quot;受众是谁&quot;定下来，导致内容与求援无法确定走向</p><p>区：做视频只是我们的赛博炫技自嗨而已；流星飞的蓝图本就是大众向，这样的问题估计会更多；大学课程应该不用考虑小学生学习（暴论）</p><p>君：我觉得应该把用户定位做好（言：是的）</p><p>言：这次广告下料太狠了；只能说我们定位没弄清楚；是时候来参与&quot;如何简明地给大众讲明白&quot;的讨论；要降低的就是&quot;自己去琢磨&quot;的门槛，而所要做的只是讲一遍模块</p><p>断懒：建议你们重申那个视频的科研定位，而不是攻略（言：同意）；我上个版本本来准备这个版本做基础基建教学，但忘了；纯粹的设备使用手册和产线讲解是否太浅层了</p><p>BEAR：主要是炫技（君大哥说的）；我和君大哥这个方案炫技来的，不急</p><p>百亿亿亿亿：只不过很多人被巨量的文字劝退了；科普就是要用超绝大白话给人举例子，起码能吸引到人</p><p>言（09-13）：自适应和自动配平都该讲，鸟老大都讲了，结果播放量评论量惨淡，难道没人看置顶评论吗；难道还得再简单、再忽略更多前提吗；科普也太深邃了</p><p>S：这个东西用就有门槛，只是自适应门槛比一般的蓝图作业高很多；因为自适应最终面向的就是新人</p><p>K：要把用户当成盲人对待（）；君：但是不能这么盲吧</p><p>c：我说基建门槛还是太高了；我怎么觉得 0 门槛，抄作业哪有门槛，修 bug 才是门槛</p><p>乾震_QzzZ：没有美观和乐趣作为动力，单靠难度还是门槛太高了，只会越来越小众；重点是降低门槛、提高趣味性；基建就是门槛太高了，而跨过门槛就已经毕业了</p><p>S 与 c（09-17）：适配度和门槛这俩是一回事吗</p><p>断懒、浅仓透：教学单独做更好，想学的会自己搜教程</p><p>PL：现在基建这么大争议的原因是主线教程太少、难度曲线不合理，应该多加基建内容；言：游戏和玩家应该互相选择，不适合就别玩 → PL：你这就属于不教而诛 → 盒え猫：多加基建势必会引起一部分人反对；言：有深度并且广泛被参与的玩法才是有生命力</p><p>塔卫二 xyIvneu_：我们是科普视频；受众不一样，这个比较适合浓度高的，zmd 比较适合理工科；c：zmd 是基建玩法，受众本来就少；Cipolla_：做成教材受众确实小了点，但我想总归会有人看；Xersyo：本质科研组；</p><p>（局 09-11 ~ 09-21；塔卫二 04-05、04-25、08-06、09-11）</p></div>',1)])])}const g=t(i,[["render",r]]);export{c as __pageData,g as default};
